+// htmlVoidElements are elements that never have an end tag.
+var htmlVoidElements = map[string]bool{
+	"area": true, "base": true, "br": true, "col": true, "embed": true, "hr": true, "img": true,
+	"input": true, "link": true, "meta": true, "param": true, "source": true, "track": true, "wbr": true,
+}
+
+// htmlContainerElements are generic containers that may wrap large parts of the document
+// (e.g. sections in AsciiDoc, Org and reStructuredText), so we don't extend the summary to their end.
+var htmlContainerElements = map[string]bool{
+	"div": true, "section": true, "article": true,
+}
+
+// endOfOpenElements tokenizes s starting at from and returns the first position >= pos
+// where no elements (other than generic containers) opened after from are left open.
+// Any end tags directly following that position closing open containers are included.
+// If s ends before that, len(s) is returned.
+func endOfOpenElements(s string, from, pos int) int {
+	var stack []string
+	offset := from
+	end := -1
+	z := html.NewTokenizer(strings.NewReader(s[from:]))
+	for {
+		tt := z.Next()
+		if tt == html.ErrorToken {
+			if end != -1 {
+				return end
+			}
+			// io.EOF or malformed HTML; include the rest.
+			return len(s)
+		}
+		offset += len(z.Raw())
+
+		if end != -1 {
+			// Include whitespace and end tags closing the open containers, if any.
+			switch tt {
+			case html.TextToken:
+				if strings.TrimSpace(string(z.Raw())) == "" {
+					continue
+				}
+			case html.EndTagToken:
+				name, _ := z.TagName()
+				if n := len(stack); n > 0 && stack[n-1] == string(name) {
+					stack = stack[:n-1]
+					end = offset
+					continue
+				}
+			}
+			return end
+		}
+
+		switch tt {
+		case html.StartTagToken:
+			name, _ := z.TagName()
+			tag := string(name)
+			if htmlVoidElements[tag] {
+				break
+			}
+			// Handle the most common implied end tags.
+			if n := len(stack); n > 0 && (tag == "p" || tag == "li") && stack[n-1] == tag {
+				stack = stack[:n-1]
+			}
+			stack = append(stack, tag)
+		case html.EndTagToken:
+			name, _ := z.TagName()
+			tag := string(name)
+			for i := len(stack) - 1; i >= 0; i-- {
+				if stack[i] == tag {
+					// Also implicitly closes any unclosed elements opened after this one.
+					stack = stack[:i]
+					break
+				}
+			}
+		}
+
+		if offset >= pos && onlyContainersOpen(stack) {
+			if len(stack) == 0 {
+				return offset
+			}
+			end = offset
+		}
+	}
+}
+
+func onlyContainersOpen(stack []string) bool {
+	for _, tag := range stack {
+		if !htmlContainerElements[tag] {
+			return false
+		}
+	}
+	return true
+}
