+// Many page render errors used to make the build hang forever: after
+// maxErrors the renderers stopped consuming pages while the page walker was
+// blocked sending to the full pages channel.
+func TestErrorManyPageRenderErrorsDoesNotHang(t *testing.T) {
+	// Not parallel: these settings are process global. They make the race
+	// hit (almost) every time on unfixed code.
+	t.Setenv("HUGO_NUMWORKERMULTIPLIER", "2")
+	defer runtime.GOMAXPROCS(runtime.GOMAXPROCS(1))
+
+	var filesBuilder strings.Builder
+	filesBuilder.WriteString(`
+-- hugo.toml --
+disableKinds = ["taxonomy", "term", "rss", "sitemap"]
+-- layouts/single.html --
+{{ (resources.Get "missing.svg").Content }}
+-- layouts/list.html --
+{{ (resources.Get "missing.svg").Content }}
+`)
+	for i := range 50 {
+		filesBuilder.WriteString(fmt.Sprintf(`
+-- content/p%d.md --
+---
+title: p%d
+---
+`, i, i))
+	}
+	files := filesBuilder.String()
+
+	for i := range 10 {
+		done := make(chan error, 1)
+		go func() {
+			_, err := TestE(t, files)
+			done <- err
+		}()
+
+		select {
+		case err := <-done:
+			qt.Assert(t, err, qt.Not(qt.IsNil))
+			qt.Assert(t, err.Error(), qt.Contains, "failed to render pages")
+			qt.Assert(t, err.Error(), qt.Contains, filepath.FromSlash("/layouts/"))
+		case <-time.After(30 * time.Second):
+			t.Fatalf("build %d did not finish: hung after page render errors", i)
+		}
+	}
+}
