+func TestBuildBrowserFieldDisabledModule(t *testing.T) {
+	t.Parallel()
+
+	files := `
+-- hugo.toml --
+disableKinds = ["taxonomy", "term", "rss", "sitemap"]
+-- assets/main.js --
+import value from "browser-disabled";
+import value2 from "browser-disabled-ext";
+console.log(value, value2);
+-- node_modules/browser-disabled/package.json --
+{
+  "name": "browser-disabled",
+  "version": "1.0.0",
+  "main": "index.js",
+  "browser": {
+    "./util.inspect.js": false
+  }
+}
+-- node_modules/browser-disabled/index.js --
+module.exports = require("./util.inspect");
+-- node_modules/browser-disabled/util.inspect.js --
+module.exports = "EXCLUDED-FROM-BROWSER";
+-- node_modules/browser-disabled-ext/package.json --
+{
+  "name": "browser-disabled-ext",
+  "version": "1.0.0",
+  "main": "index.js",
+  "browser": {
+    "./util.inspect.js": false
+  }
+}
+-- node_modules/browser-disabled-ext/index.js --
+module.exports = require("./util.inspect.js");
+-- node_modules/browser-disabled-ext/util.inspect.js --
+module.exports = "EXCLUDED-FROM-BROWSER-EXT";
+-- layouts/home.html --
+{{ $js := resources.Get "main.js" | js.Build }}
+RESULT:<pre>{{ $js.Content }}</pre>
+`
+
+	b := hugolib.Test(t, files, hugolib.TestOptOsFs())
+
+	b.AssertFileContent("public/index.html",
+		"(disabled):node_modules/browser-disabled/util.inspect",
+		"(disabled):node_modules/browser-disabled-ext/util.inspect.js",
+		"! EXCLUDED-FROM-BROWSER",
+	)
+
+	// A missing file is still an error.
+	files = strings.Replace(files, `require("./util.inspect")`, `require("./doesnotexist")`, 1)
+	_, err := hugolib.TestE(t, files, hugolib.TestOptOsFs())
+	b.Assert(err, qt.ErrorMatches, `(?s).*Could not resolve "./doesnotexist".*`)
+}

